mapper.sql:
WHERE BINARY t.tenant_type!='INTERNAL'
        AND t.tenant_type=#{filter.tenantType}
        AND t.tenant_id=#{filter.tenantId}
        AND t.owner_ref_id=#{filter.ownerRefId}
        AND t.tenant_name LIKE #{filter.tenantName} ESCAPE '!'
        AND t.owner_status=#{filter.ownerStatus}
        AND t.security_status=#{filter.securityStatus}

WHERE m.tenant_id=#{tenantId}
        AND m.account_id=#{filter.accountId}
        AND a.email_masked LIKE #{filter.emailMasked} ESCAPE '!'
        AND m.member_type=#{filter.memberType}
        AND m.status=#{filter.memberStatus}

mapper.select:
SELECT ,rp.role_permission_id rolePermissionId,rp.status rolePermissionStatus,
 WHERE g.tenant_member_id=#{memberId} AND rp.permission_id=#{permissionId}
ORDER BY g.tenant_member_role_id,rp.role_permission_id LIMIT #{size} OFFSET #{offset}
